"use client";

import { useState, useRef, useEffect } from "react";
import { useRouter } from "next/navigation";
import { 
  ArrowLeft, Download, RotateCw, Image as ImageIcon,
  Check, Layout, Sparkles, Loader2, Share2, Info, CheckCircle2
} from "lucide-react";
import { toPng } from "html-to-image";
import { supabase } from "@/lib/supabase";

// --- 🏰 FLYER TEMPLATES ---

const MinimalistElite = ({ store, products, qrCode }: any) => (
  <div className="w-[1080px] h-[1080px] bg-slate-900 relative overflow-hidden flex flex-col items-center justify-between p-20 text-center">
    {/* Use the first product's image as background */}
    <img src={products[0]?.display_image} crossOrigin="anonymous" className="absolute inset-0 w-full h-full object-cover opacity-40" alt="" />
    <div className="absolute inset-0 bg-gradient-to-t from-[#043927] via-transparent to-[#043927]/60" />
    <div className="relative z-10 space-y-6">
      <div className="w-32 h-32 bg-white rounded-full mx-auto p-1 shadow-2xl overflow-hidden border-4 border-emerald-500">
         <img src={store?.logo_url} crossOrigin="anonymous" className="w-full h-full object-cover rounded-full" alt="" />
      </div>
      <h2 className="text-white text-4xl font-black uppercase tracking-widest italic">{store?.name}</h2>
    </div>
    <h1 className="relative z-10 text-white text-[120px] font-black leading-none tracking-tighter uppercase italic">WE'VE <br/> <span className="text-emerald-400">UPGRADED.</span></h1>
    <div className="relative z-10 bg-white p-8 rounded-[3rem] flex items-center gap-8 shadow-2xl">
      <img src={qrCode} crossOrigin="anonymous" className="w-32 h-32" alt="QR" />
      <div className="text-left">
        <p className="text-gray-900 font-black text-2xl uppercase italic">Scan to shop</p>
        <p className="text-emerald-600 font-mono">storelink.ng/{store?.slug}</p>
      </div>
    </div>
  </div>
);

const ProductTrio = ({ store, products, qrCode }: any) => (
  <div className="w-[1080px] h-[1080px] bg-white relative overflow-hidden flex flex-col">
    <div className="p-16 bg-[#043927] text-center border-b-[16px] border-emerald-500">
      <h1 className="text-white text-7xl font-black uppercase italic leading-none">NO MORE "DM FOR PRICE"</h1>
    </div>
    <div className="flex-1 grid grid-cols-3 gap-6 p-10 bg-gray-100">
      {products.map((p: any, i: number) => (
        <div key={i} className="relative rounded-[2.5rem] overflow-hidden bg-white shadow-2xl border-4 border-white">
          <img src={p.display_image} crossOrigin="anonymous" className="w-full h-full object-cover" alt="" />
          <div className="absolute bottom-0 inset-x-0 p-8 bg-gradient-to-t from-black/90 to-transparent">
            <p className="text-emerald-400 font-black text-4xl">₦{p.price?.toLocaleString()}</p>
          </div>
        </div>
      ))}
    </div>
    <div className="p-12 flex justify-between items-center bg-white border-t-2 border-gray-100">
      <div className="flex items-center gap-6">
        <img src={store?.logo_url} crossOrigin="anonymous" className="w-24 h-24 rounded-full object-cover border-4 border-emerald-500 shadow-lg" alt="" />
        <h2 className="text-gray-900 text-4xl font-black uppercase italic tracking-tighter">{store?.name}</h2>
      </div>
      <img src={qrCode} crossOrigin="anonymous" className="w-32 h-32" alt="QR" />
    </div>
  </div>
);

// --- 🚀 MAIN STUDIO PAGE ---

export default function FlyerStudio() {
  const router = useRouter();
  const exportRef = useRef<HTMLDivElement>(null);
  
  const [loading, setLoading] = useState(true);
  const [generating, setGenerating] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);
  const [lastGeneratedFlyer, setLastGeneratedFlyer] = useState<string | null>(null);
  const [store, setStore] = useState<any>(null);
  const [allProducts, setAllProducts] = useState<any[]>([]);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [designIndex, setDesignIndex] = useState(0);

  useEffect(() => { fetchData(); }, []);

  const fetchData = async () => {
    setLoading(true);
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return router.push("/login");

      const { data: storeData } = await supabase.from("stores").select("*").eq("owner_id", user.id).single();
      const { data: productsData } = await supabase.from("products").select("*").eq("store_id", storeData?.id).order('created_at', { ascending: false });

      const resolveUrl = (path: any, bucket: string) => {
        if (!path) return "";
        // Handle if image_urls is an array or a string
        const actualPath = Array.isArray(path) ? path[0] : path;
        if (actualPath.startsWith('http')) return actualPath;
        const { data } = supabase.storage.from(bucket).getPublicUrl(actualPath);
        return data.publicUrl;
      };

      // MAP DB DATA TO COMPONENT DATA
      const finalProducts = (productsData || []).map(p => ({
        ...p,
        display_image: resolveUrl(p.image_urls, 'products') // FIXED: uses plural image_urls
      }));

      setStore({
        ...storeData,
        logo_url: resolveUrl(storeData?.logo_url, 'stores')
      });
      
      setAllProducts(finalProducts);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const toggleProduct = (id: string) => {
    if (selectedIds.includes(id)) {
      setSelectedIds(selectedIds.filter(i => i !== id));
    } else if (selectedIds.length < 3) {
      setSelectedIds([...selectedIds, id]);
    }
  };

  const downloadFlyer = async () => {
    if (!exportRef.current) return;
    setGenerating(true);
    await new Promise(r => setTimeout(r, 800));

    try {
      const dataUrl = await toPng(exportRef.current, { cacheBust: true, pixelRatio: 2, backgroundColor: '#ffffff' });
      const link = document.createElement('a');
      link.download = `Empire-Flyer-${Date.now()}.png`;
      link.href = dataUrl;
      link.click();
      setLastGeneratedFlyer(dataUrl);
      setShowSuccess(true);
    } catch (err) {
      console.error(err);
      alert("CORS error: Check Supabase Storage permissions.");
    } finally {
      setGenerating(false);
    }
  };

  const selectedProducts = allProducts.filter(p => 
    selectedIds.some(id => String(id) === String(p.id))
  );

  const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=400x400&color=043927&data=https://storelink.ng/${store?.slug}`;

  if (loading) return <div className="h-screen flex items-center justify-center font-black uppercase italic animate-pulse">Syncing Empire Assets...</div>;

  return (
    <div className="min-h-screen bg-gray-50 pb-20 relative">
      <nav className="bg-white border-b p-4 flex justify-between items-center px-6 sticky top-0 z-50">
        <button onClick={() => router.back()}><ArrowLeft /></button>
        <h1 className="font-black uppercase italic text-emerald-900">Flyer Studio</h1>
        <button onClick={() => setDesignIndex((prev) => (prev + 1) % 2)} className="bg-emerald-950 text-white px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest">
          <RotateCw size={14} className="inline mr-2" /> Design {designIndex + 1}
        </button>
      </nav>

      <div className="max-w-7xl mx-auto p-6 grid grid-cols-1 lg:grid-cols-2 gap-10">
        {/* PICKER */}
        <div className="bg-white p-8 rounded-[3rem] border shadow-sm">
          <h2 className="font-black uppercase italic text-lg mb-6 flex items-center gap-2">
            <Layout className="text-emerald-600" size={20}/> 1. Pick 3 Best Sellers
          </h2>
          <div className="grid grid-cols-3 gap-3">
            {allProducts.map((p) => {
              const isSelected = selectedIds.includes(p.id);
              return (
                <button key={p.id} onClick={() => toggleProduct(p.id)} className={`relative aspect-square rounded-3xl overflow-hidden border-4 transition-all ${isSelected ? 'border-emerald-600' : 'border-transparent opacity-60'}`}>
                  <img src={p.display_image} className="w-full h-full object-cover" alt="" />
                  {isSelected && (
                    <div className="absolute inset-0 bg-emerald-600/40 flex items-center justify-center">
                      <div className="bg-white text-emerald-600 rounded-full p-2 shadow-2xl"><Check size={24} strokeWidth={4} /></div>
                    </div>
                  )}
                </button>
              );
            })}
          </div>
        </div>

        {/* PREVIEW */}
        <div className="lg:sticky lg:top-24 h-fit">
          <div className="bg-gray-200 aspect-square rounded-[3.5rem] shadow-inner relative overflow-hidden flex items-center justify-center">
             <div 
               ref={exportRef} 
               style={{ width: '1080px', height: '1080px', transform: 'scale(0.35)', transformOrigin: 'center center', position: 'absolute' }}
             >
                {selectedIds.length === 3 ? (
                   <>
                     {designIndex === 0 && <MinimalistElite store={store} products={selectedProducts} qrCode={qrUrl} />}
                     {designIndex === 1 && <ProductTrio store={store} products={selectedProducts} qrCode={qrUrl} />}
                   </>
                ) : (
                  <div className="w-full h-full bg-white flex flex-col items-center justify-center text-gray-300">
                     <ImageIcon size={200} className="opacity-10 mb-8" />
                     <h2 className="text-7xl font-black uppercase italic tracking-tighter text-center">Pick 3 Products <br/> to generate</h2>
                  </div>
                )}
             </div>
          </div>
          <button disabled={selectedIds.length < 3 || generating} onClick={downloadFlyer} className="w-full mt-6 py-6 bg-emerald-950 text-white rounded-[2rem] font-black uppercase tracking-widest shadow-xl disabled:opacity-20 flex items-center justify-center gap-4">
             {generating ? <Loader2 className="animate-spin" /> : <Download />} Download Flyer
          </button>
        </div>
      </div>

      {/* --- SUCCESS OVERLAY --- */}
      {showSuccess && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-[#043927]/95 backdrop-blur-xl">
          <div className="bg-white rounded-[3.5rem] p-10 text-center space-y-6 max-w-md w-full shadow-2xl">
            <CheckCircle2 size={60} className="mx-auto text-emerald-500" />
            <h2 className="text-4xl font-black uppercase italic tracking-tighter">Empire Level! 🏰</h2>
            <div className="aspect-square w-56 mx-auto rounded-3xl overflow-hidden border-8 border-gray-50 shadow-2xl rotate-2">
              <img src={lastGeneratedFlyer || ''} className="w-full h-full object-cover" alt="" />
            </div>
            <button 
              onClick={() => window.open(`https://wa.me/?text=${encodeURIComponent('Our new storefront is LIVE! 🏰✨\n\nShop here: storelink.ng/' + store?.slug)}`, '_blank')} 
              className="w-full py-5 bg-emerald-600 text-white rounded-[2rem] font-black uppercase tracking-widest shadow-xl flex items-center justify-center gap-3"
            >
              <Share2 size={20} /> Share to WhatsApp
            </button>
            <button onClick={() => setShowSuccess(false)} className="text-gray-400 uppercase font-black text-xs">Close</button>
          </div>
        </div>
      )}
    </div>
  );
}